traits.gx:
check_expr = {
	value = num_cavalry
	greater_than = { value = num_units  multiply = 0.4 }
}

check_expr = {
	value = num_infantry
	greater_than = { value = num_units  multiply = 0.8 }
}

traits.gxl:
if = {
	limit = { is_leading_army_group = yes }
	check_variable = { num_units > 99 }
}
else = {
	check_variable = { num_units > 23 }
}

traits.gx:
OR = {
	has_flanked_opponent = yes
	opponent = { has_flanked_opponent = yes }
}

traits.raw:
new_commander_weight = {
	base = 1
	modifier = {
		set_temp_variable = { trait_chance = FROM.modifier@commando_trait_chance_factor }
		add_to_temp_variable = { var = trait_chance value = 1 }
		factor = trait_chance
	}
	modifier = {
		factor = 0.2
		FROM = { NOT = { has_done_agency_upgrade = upgrade_commando_training } }
	}
}

